        var asm = Assembly.LoadFrom(dll);
        foreach (var t in asm.GetTypes().Where(t => t.Name.Contains("Resource") && t.IsPublic))
            Console.WriteLine($"{Path.GetFileName(dll)}: {t.FullName}");
    }
}
